shader:
// Zoom Punch - punch-in hook transition.
// A accelerates into the centre (power-2.5 ease-in in log-zoom space); B starts deep and glides out on a
// normalized exponential (expo-out) with one soft overshoot lobe past rest. Motion blur is integrated over a
// virtual shutter (jittered taps along the real zoom path), so the blur grows with speed, peaks at the cut and
// the cut itself happens between two fully streaked frames.
// Every zoom is a UNIFORM scale about the centre (straight lines stay straight); the overshoot (< 1x) samples
// at most ~1.5 % mirror-wrapped border per side, softened by the remaining radial smear.
// Extras at the peak: short barrel bulge (pinned at the corners, only on the streaked frames), faint spectral
// fringe along the streaks, small exposure lift with a vignette.

const float ZP_CUT = 0.55;     // MUST equal the preset "anchor" (zoom-punch.json) - edit both together
const int ZP_TAPS = 32;
const float ZP_PI = 3.14159265;

// Hoskins hash12 on the integer pixel: unstructured per-pixel shutter jitter (static, so it never boils)
float zpHash(vec2 uv) {
    vec2 px = floor(uv * resolution);
    vec3 p3 = fract(vec3(px.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float zpPeak(float t, float w) {
    float x = (t - ZP_CUT) / w;
    return exp(-x * x);
}

// log of the zoom factor at progress t: > 0 zoomed in, < 0 overshoot past rest (zoomed out)
float zpLogZoom(float t) {
    float depth = log(1.0 + 1.25 * zoom);
    if (t < ZP_CUT) {
        float a = clamp(t / ZP_CUT, 0.0, 1.0);
        return depth * a * a * sqrt(a);
    }
    float s = clamp((t - ZP_CUT) / (1.0 - ZP_CUT), 0.0, 1.0);
    // normalized expo-out: exactly depth*1.1 at s = 0 and exactly 0 at s = 1 (30 fps @ 0.36 s: 1.66x, 1.18x, 1.05x, ~1x)
    float k = exp(-5.0);
    float settle = depth * 1.1 * (exp(-5.0 * s) - k) / (1.0 - k);
    // one soft overshoot lobe past rest that starts and lands with zero speed
    float sl = sin(ZP_PI * clamp((s - 0.3) / 0.7, 0.0, 1.0));
    return settle - 0.06 * bounce * sl * sl;
}

vec2 zpMap(vec2 uv, float t) {
    vec2 d = uv - 0.5;
    // lens bulge: barrel magnification of the centre, pinned at the corners; lives only on the streaked frames
    // around the hit (a touch longer on A's side, gone by B's medium-blur frame)
    vec2 q = d * vec2(ratio, 1.0);
    float r2 = dot(q, q) / (0.25 * (ratio * ratio + 1.0));
    float bw = t < ZP_CUT ? 0.10 : 0.075;
    d *= 1.0 - 0.22 * zpPeak(t, bw) * (1.0 - r2);
    // uniform zoom (also for the overshoot: mirror-wrapped edges are allowed and the band is tiny)
    d *= exp(-zpLogZoom(t));
    return 0.5 + d;
}

vec4 transition(vec2 uv) {
    float p = progress;
    float win = clamp(p * 14.0, 0.0, 1.0) * clamp((1.0 - p) * 14.0, 0.0, 1.0);
    float sh = 0.075 * blur * win;
    // shorter shutter once B has glided out: the overshoot frames keep a light radial smear (hides the mirror
    // seam), the landing frame itself has zero blur
    sh *= mix(1.0, 0.5, smoothstep(0.2, 0.45, (p - ZP_CUT) / (1.0 - ZP_CUT)));
    float j = zpHash(uv);
    // the shutter never straddles the cut: near it the window slides to stay on one side, so the hard cut
    // lands between two fully streaked frames (no double exposure, no sharp frame at the hit)
    bool sideB = p >= ZP_CUT;
    float mid = sideB ? max(p, ZP_CUT + 0.5 * sh) : min(p, ZP_CUT - 0.5 * sh - 0.0001);
    vec3 acc = vec3(0.0);
    vec3 wsum = vec3(0.0);
    for (int i = 0; i < ZP_TAPS; i++) {
        float f = (float(i) + j) / float(ZP_TAPS);
        float t = clamp(mid + sh * (f - 0.5), 0.0, 1.0);
        vec2 st = zpMap(uv, t);
        vec4 c = sideB ? getB(st) : getA(st);
        float k = 0.35 * (1.0 - 2.0 * f);
        vec3 w = vec3(1.0 + k, 1.0, 1.0 - k);
        acc += c.rgb * w;
        wsum += w;
    }
    vec3 col = acc / wsum;
    float pk = zpPeak(p, 0.09);
    vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
    float r2 = dot(q, q) / (0.25 * (ratio * ratio + 1.0));
    col *= (1.0 + 0.10 * pk) * (1.0 - 0.18 * pk * smoothstep(0.25, 1.0, r2));
    return vec4(col, 1.0);
}
